let state;
const list = document.getElementById("books");
const filter = document.querySelector("[data-hook=filter]");
// A genre as the filter compares it: spaces at either end aside, and repeated ones as one.
const spaced = (text) => text.trim().split(" ").filter(Boolean).join(" ");
const render = () => {
  const books = state.data.items;
  const chosen = filter.value;
  const genres = [...new Set(books.map((book) => book.genre))];
  filter.replaceChildren(new Option("Todos", ""), ...genres.map((genre) => new Option(genre, genre)));
  filter.value = genres.includes(chosen) ? chosen : "";
  list.replaceChildren(...books.map((record) => {
    const item = document.createElement("li");
    item.dataset.hook = "item";
    item.hidden = Boolean(filter.value) && spaced(record.genre) !== spaced(filter.value);
    const genre = document.createElement("span");
    genre.dataset.hook = "category";
    genre.textContent = record.genre;
    const remove = document.createElement("button");
    remove.dataset.hook = "item-remove";
    remove.textContent = "Remover " + record.name;
    remove.addEventListener("click", () =>
      tessera
        .call("data.patch", { operations: [{ op: "remove", collection: "items", id: record.id, revisionCount: state.revisions.items[record.id] }] })
        .then(load),
    );
    item.append(record.name + " (nota " + record.rating + ") ", genre, " ", remove);
    return item;
  }));
};
const load = () => tessera.call("data.read").then((read) => { state = read; render(); });
load();
filter.addEventListener("change", render);
document.querySelector("[data-hook=item-add]").addEventListener("click", () => {
  const name = document.querySelector("[data-hook=item-name]").value.trim();
  const genre = document.querySelector("[data-hook=item-category]").value;
  const rating = Math.min(5, Math.max(1, Math.round(Number(document.getElementById("rating").value) || 3)));
  if (!name) return;
  tessera.call("data.patch", { operations: [{ op: "add", collection: "items", record: { name, genre, rating } }] }).then(load);
});
